#include &lt;iostream&gt;
#include &lt;filesystem&gt;

int main() {
    // https://commons.wikimedia.org/wiki/File:Mandrill-k-means.png
    mm::Image img_rgb = mm::read("https://upload.wikimedia.org/wikipedia/commons/a/ab/Mandrill-k-means.png"); // (M, N, 3), uint8

    // Canal alfa: gradiente horizontal 0 -&gt; 255 (esquerda -&gt; direita)
    int h = img_rgb.h, w = img_rgb.w;
    mm::Image alpha(h, w);
    for (int x = 0; x &lt; w; x++) {
