    mm::Image img_rgba(h, w, 4);
    for (int y = 0; y &lt; h; y++) {
        for (int x = 0; x &lt; w; x++) {
            for (int ch = 0; ch &lt; 3; ch++) {
                img_rgba.at(y, x, ch) = img_rgb.at(y, x, ch);
            }
            img_rgba.at(y, x, 3) = alpha.at(y, x);
