    const int CLASSE = 0;   // 0 = moeda (única categoria neste exemplo)

    std::cout &lt;&lt; std::setw(4) &lt;&lt; "cls" &lt;&lt; std::setw(9) &lt;&lt; "cx_n" &lt;&lt; std::setw(9) &lt;&lt; "cy_n" 
