        std::cout &lt;&lt; std::setw(4) &lt;&lt; CLASSE &lt;&lt; std::setw(9) &lt;&lt; std::fixed &lt;&lt; std::setprecision(4)
                  &lt;&lt; cx_n &lt;&lt; std::setw(9) &lt;&lt; cy_n &lt;&lt; std::setw(9) &lt;&lt; w_n &lt;&lt; std::setw(9) &lt;&lt; h_n &lt;&lt; "\n";

        cv::rectangle(img_bbox, cv::Point(x0, y0), cv::Point(x0 + w, y0 + h), cv::Scalar(0, 255, 0), 4);
